"""Bilnov - CORRECTION MOBILE outil de mesure : en mode Mesure sur telephone, le doigt deplace le CURSEUR (le plan reste fixe), tap = valider un point (tolerance 8px), 2 doigts = zoom. Ecouteurs tactiles natifs passive:false. A appliquer apres le deploiement courant."""
import base64, os, sys, subprocess
EDITS=[["src/components/CadViewer.tsx", "touch-refs", "dG91Y2hMYXllclJlZg==", "ICBjb25zdCBzZWdJbmRleFJlZiA9IHVzZVJlZjxTZWdtZW50SW5kZXggfCBudWxsPihudWxsKTs=", ""], ["src/components/CadViewer.tsx", "touch-effect", "Ly8gLS0tIFRhY3RpbGUgOiBsZSBkb2lndCBkZXBsYWNlIGxlIENVUlNFVVI=", "ICBmdW5jdGlvbiBjZW50ZXJXb3JsZCgpOiBQdCB8IG51bGwgewogICAgY29uc3QgY29udCA9IGNvbnRhaW5lclJlZi5jdXJyZW50OyBpZiAoIWNvbnQpIHJldHVybiBudWxsOwogICAgY29uc3QgYyA9IHNjcmVlblRvV29ybGQoY29udC5jbGllbnRXaWR0aCAvIDIsIGNvbnQuY2xpZW50SGVpZ2h0IC8gMik7CiAgICByZXR1cm4gYyA/IHNuYXBXb3JsZChjKSA6IG51bGw7CiAgfQ==", ""], ["src/components/CadViewer.tsx", "touch-layer", "cmVmPXt0b3VjaExheWVyUmVmfQ==", "ICAgICAgICA8ZGl2IHJlZj17Y29udGFpbmVyUmVmfSBjbGFzc05hbWU9ImZsZXgtMSBiZy13aGl0ZSIgc3R5bGU9e3sgY3Vyc29yOiB0b29sID09PSAncGFuJyA/ICdkZWZhdWx0JyA6ICdjcm9zc2hhaXInIH19IC8+", ""], ["src/components/CadViewer.tsx", "reticle-hide", "eyFzbmFwSG92ZXIgJiYgKAogICAgICAgICAgICAgICAgICA8ZGl2IGNsYXNzTmFtZT0iYWJzb2x1dGUgbGVmdC0xLzIgdG9wLTEvMg==", "", ""]]
def d(s): return base64.b64decode(s).decode('utf-8')
def parse(a):
    root,build='.',True; i=0
    while i<len(a):
        if a[i]=='--root': root=a[i+1]; i+=2; continue
        if a[i]=='--no-build': build=False
        i+=1
    return root,build
def run(cmd,root):
    print("\n$"," ".join(cmd)); r=subprocess.run(cmd,cwd=root)
    if r.returncode: print("!! echec (rc=%d)."%r.returncode); sys.exit(r.returncode)
def main():
    root,build=parse(sys.argv[1:]); print("== Bilnov - correction tactile mesure (doigt = curseur) ==")
    cache={}
    for f,name,dm,o,nw in EDITS:
        p=os.path.join(root,f)
        if not os.path.exists(p): print("!! introuvable:",f); sys.exit(1)
        src=cache.get(p) or open(p,encoding='utf-8').read(); marker,old,new=d(dm),d(o),d(nw)
        if marker in src: print("  = deja",name); cache[p]=src; continue
        if old not in src: print("!! ANCRE KO:",name); sys.exit(2)
        src=src.replace(old,new,1); cache[p]=src; print("  ~ patche",name)
    for p,src in cache.items(): open(p,'w',encoding='utf-8').write(src)
    run(["npm","install"],root); run(["npm","run","test"],root)
    if build: run(["npm","run","build"],root)
    print("\nOK. Correction tactile appliquee. Aucun git push.")
if __name__=='__main__': main()
